CREATE TABLE public."Profile"
(
    "ID"    uuid PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
    "Name"  text NOT NULL,
    "Role"  text NOT NULL CHECK ("Role" IN ('student', 'professor')),
    "Email" text UNIQUE
);

CREATE TABLE public."Classes"
(
    "ClassID"     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfessorID" uuid        NOT NULL REFERENCES public."Profile" ("ID") ON DELETE CASCADE,
    "ClassName"   text        NOT NULL,
    "Description" text,
    "ClassCode"   text        NOT NULL UNIQUE,
    "CreatedAt"   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public."Enrollment"
(
    "EnrollmentID" bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "StudentID"    uuid        NOT NULL REFERENCES public."Profile" ("ID") ON DELETE CASCADE,
    "ClassID"      bigint      NOT NULL REFERENCES public."Classes" ("ClassID") ON DELETE CASCADE,
    "EnrolledAt"   timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("StudentID", "ClassID")
);

CREATE TABLE public."Challenges"
(
    "ChallengeID"   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ClassID"       bigint      NOT NULL REFERENCES public."Classes" ("ClassID") ON DELETE CASCADE,
    "Title"         text        NOT NULL,
    "Description"   text,
    "ChallengeType" text,
    "Points"        integer     NOT NULL DEFAULT 0,
    "CodeLanguage"  text,
    "CreatedAt"     timestamptz NOT NULL DEFAULT now(),
    "MaxAttempts"   smallint,
    "Hidden"        boolean     NOT NULL DEFAULT false,
    "IsPublished"   boolean     NOT NULL DEFAULT false
);

CREATE TABLE public."Locations"
(
    "LocationID"  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "ChallengeID" bigint        NOT NULL REFERENCES public."Challenges" ("ChallengeID") ON DELETE CASCADE,
    "Latitude"    numeric(9, 6) NOT NULL,
    "Longitude"   numeric(9, 6) NOT NULL,
    "Radius"      integer       NOT NULL
);

CREATE TABLE public."Solutions"
(
    "ChallengeID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
        REFERENCES public."Challenges" ("ChallengeID") ON DELETE CASCADE,
    "Solution"    text NOT NULL
);

CREATE TABLE public."Submission"
(
    "SubmissionID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentID"    uuid        NOT NULL REFERENCES public."Profile" ("ID") ON DELETE CASCADE,
    "ChallengeID"  bigint      NOT NULL REFERENCES public."Challenges" ("ChallengeID") ON DELETE CASCADE,
    "Score"        integer,
    "Output"       text,
    "Code"         text,
    "Language"     text,
    "Status"       text,
    "SubmittedAt"  timestamptz NOT NULL DEFAULT now(),
    "AttemptNum"   smallint,
    "Feedback"     text
        CONSTRAINT "Submission_Feedback_length" CHECK (char_length("Feedback") <= 5000)
);

CREATE TABLE public."TestCase"
(
    "TestCaseID"     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ChallengeID"    bigint  NOT NULL REFERENCES public."Challenges" ("ChallengeID") ON DELETE CASCADE,
    "Input"          text,
    "Score"          smallint,
    "ExpectedOutput" text,
    "CreatedAt"      timestamptz,
    "hiddenFrom"     boolean,
    "Hidden"         boolean NOT NULL DEFAULT false
);

ALTER TABLE public."Profile"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Classes"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Enrollment"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Challenges"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Locations"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Solutions"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Submission"
    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."TestCase"
    ENABLE ROW LEVEL SECURITY;
